export const FRAG = {"MODES": [["ESI+", "ESI+  [M+H]+"], ["ESI+Na", "ESI+  [M+Na]+"], ["ESI+NH4", "ESI+  [M+NH4]+"], ["ESI-", "ESI−  [M−H]−"], ["EI", "EI  M•+"]], "LIKELY": 0.65, "POSSIBLE": 0.4, "REFS": {"ei": "McLafferty FW, Tureček F. Interpretation of Mass Spectra, 4th ed. University Science Books, 1993.", "mclafferty": "McLafferty FW. Anal. Chem. 1959, 31, 82-87; McLafferty & Tureček, Interpretation of Mass Spectra, 1993.", "esi": "Demarque DP et al. Fragmentation reactions using electrospray ionization mass spectrometry. Nat. Prod. Rep. 2016, 33, 432-455 (doi:10.1039/C5NP00073D).", "even": "Karni M, Mandelbaum A. The even-electron rule. Org. Mass Spectrom. 1980, 15, 53-64.", "rda": "Fabre N et al. J. Am. Soc. Mass Spectrom. 2001, 12, 707-715 (flavonoid 1,3A / 1,3B ions); Ma YL et al. Rapid Commun. Mass Spectrom. 1997, 11, 1357-1364.", "glyco": "Domon B, Costello CE. Glycoconjugate J. 1988, 5, 397-409 (B / Y ions); Cuyckens F, Claeys M. J. Mass Spectrom. 2004, 39, 1-15.", "radical": "Hvattum E, Ekeberg D. J. Mass Spectrom. 2003, 38, 43-49 (radical aglycone [Y0-H]•−).", "peptide": "Roepstorff P, Fohlman J. Biomed. Mass Spectrom. 1984, 11, 601 (b / y ions); Paizs B, Suhai S. Mass Spectrom. Rev. 2005, 24, 508-548 (mobile proton, immonium ions).", "lipid": "Hsu FF, Turk J. J. Am. Soc. Mass Spectrom. 2003, 14, 352-363 (phosphocholine m/z 184; PE loss of 141).", "tms": "Harvey DJ, Vouros P. Mass Spectrom. Rev. 2020, 39, 105-211 (TMS derivatives: m/z 73, 147, M−15).", "chlorogenic": "Clifford MN et al. J. Agric. Food Chem. 2003, 51, 2900-2911 (quinate m/z 191, caffeate 179).", "sodium": "Cancilla MT et al. J. Am. Soc. Mass Spectrom. 1999, 10, 1145 (sodiated glycans: cross-ring cleavage); Hsu FF, Turk J. J. Am. Soc. Mass Spectrom. 2003, 14, 352 ([M+Na−59]+ of PC); Demarque et al. 2016."}, "LOSS_TEXT": {"alcohol": ["Protonation of the OH makes water a good leaving group: the C–O bond pair goes to O and H2O leaves, giving the carbocation (or, with a neighbouring H, a double bond).", "The radical cation loses water: a hydrogen (often from C-4, through a six-membered ring) moves to the OH as the C–O bond breaks (1,2- / 1,4-elimination)."], "carboxylic acid": ["The protonated acid loses water from its OH (giving the acylium ion), or CO2 / HCOOH; the carboxylate anion loses CO2, its C–C bond pair staying on the carbon.", null], "primary amine": ["The protonated NH3+ group leaves as ammonia: the C–N bond pair goes to N, leaving a carbocation (or an alkene after a 1,2-H shift).", null], "primary amide": ["The protonated amide loses ammonia, giving the acylium ion.", null], "methyl ester": ["Protonation at the ester O-methyl oxygen; the acyl–O bond pair goes to O and methanol leaves, giving the acylium ion.", null], "methyl ether": ["The protonated methoxy group leaves as methanol, giving the carbocation.", null], "aryl methoxy group": ["Homolysis of the O–CH3 bond: a methyl radical leaves and the stable phenoxyl-type radical ion remains (an exception to the even-electron rule, typical of methoxylated flavonoids and phenolic acids).", null], "tert-butyl group": ["Protonation at the heteroatom; the O/N–C(CH3)3 bond pair goes to the heteroatom and the tert-butyl cation leaves as isobutene after losing a proton (E1).", null], "acetyl group, as ketene": ["Four-centre elimination: an H of the acetyl CH3 moves to the O / N as the acyl–O / N bond breaks, and ketene (CH2=C=O) leaves.", null], "alkyl chloride": ["A hydrogen on the next carbon leaves with the halogen (1,2-elimination of HX).", null], "alkyl bromide": ["A hydrogen on the next carbon leaves with the halogen (1,2-elimination of HX).", null], "alkyl fluoride": ["A hydrogen on the next carbon leaves with the halogen (1,2-elimination of HX).", null], "nitro group": ["The C–NO2 bond breaks homolytically: NO2• leaves and the aryl cation (or anion) remains.", null], "thiol": ["The protonated SH leaves as H2S, as water leaves an alcohol.", null], "sulfate / sulfonic acid": ["The S–O bond pair stays on the oxygen and SO3 leaves (sulfates: [M−H−80]−).", null], "phosphate ester": ["The protonated phosphate leaves as H3PO4 (with a neighbouring H, an alkene forms), or HPO3 is expelled and the alcohol remains (phosphopeptides: −98 / −80).", null], "trimethylsilyl group": ["A methyl radical leaves from silicon (α-cleavage at Si): the [M−CH3]+ ion of TMS derivatives, often stronger than M•+.", null], "tert-butyldimethylsilyl group": ["The tert-butyl radical leaves from silicon: [M−57]+, usually the base peak of TBDMS derivatives.", null]}, "FORMULA_TEXT": {"ring C=O (from the ring)": "The ring opens next to the C=O and carbon monoxide is expelled (ring contraction): flavones, chromones, xanthones, quinones.", "phenol (from the ring)": "The phenol ring keto-tautomerises, then expels CO (the cyclopentadiene ion remains).", "nitro group (as the nitrite)": "The nitro group rearranges to the nitrite Ar–O–N=O, which loses NO• (then often CO).", "aromatic N": "The ring opens and HCN is expelled (pyridines, anilines, indoles).", "C-glycoside (cross-ring, 0,3X)": "C-glycosides cannot lose the sugar whole; the sugar ring breaks across two bonds instead (0,3X: −90; 0,2X: −120).", "C-glycoside (cross-ring, 0,2X)": "C-glycosides cannot lose the sugar whole; the sugar ring breaks across two bonds instead (0,2X: −120; 0,3X: −90).", "lactone / coumarin (from the ring)": "The lactone ring opens and CO2 leaves (coumarins also lose CO first).", "chromone C ring (from the ring)": "The C ring of the flavone / chromone opens and loses CO2.", "chromone C ring, as ketene (from the ring)": "The C ring loses ketene (C2H2O, −42), as flavones do in CID.", "ortho effect": "Ortho effect: the neighbouring OH / NH2 gives its hydrogen to the ester / acid oxygen through a six-membered ring, and the alcohol (or water) leaves; meta and para isomers do not do this.", "aryl methyl ether": "The methyl H moves to the ring and formaldehyde (CH2O) leaves (anisoles: M−30).", "phenol, as formyl": "After ring opening the phenol loses the formyl radical (M−29).", "phosphocholine": "The phosphocholine head group leaves as a neutral (−183), the diacylglycerol ion remains.", "phosphoethanolamine": "Protonated phosphatidylethanolamines lose the phosphoethanolamine head group (−141)."}, "GROUP_LOSSES": [["H2O", "[CX4;!$(C=O)][OX2H1]", [1], 0, 2, false, {"EI": 0.45, "ESI+": 0.75, "ESI-": 0.35}, "alcohol"], ["H2O", "[CX3](=O)[OX2H1]", [2], 0, 2, false, {"ESI+": 0.55, "ESI-": 0.25}, "carboxylic acid"], ["CO2", "[#6][CX3](=O)[OX2H1,OX1-]", [1, 2, 3], 0, 0, false, {"EI": 0.15, "ESI+": 0.2, "ESI-": 0.9}, "carboxylic acid"], ["HCOOH", "[#6][CX3](=O)[OX2H1]", [1, 2, 3], 0, 2, false, {"ESI+": 0.45, "EI": 0.15}, "carboxylic acid"], ["NH3", "[CX4][NX3H2;!$(N[#6]=[O,S,N])]", [1], 0, 3, false, {"EI": 0.2, "ESI+": 0.75}, "primary amine"], ["NH3", "[CX3](=O)[NX3H2]", [2], 0, 3, false, {"ESI+": 0.5}, "primary amide"], ["CH3OH", "[CX3](=O)[OX2][CH3]", [2, 3], 0, 4, false, {"ESI+": 0.65, "ESI-": 0.3}, "methyl ester"], ["CH3OH", "[CX4][OX2][CH3]", [1, 2], 0, 4, false, {"ESI+": 0.4}, "methyl ether"], ["CH3•", "c[OX2][CH3]", [2], 1, 3, true, {"EI": 0.55, "ESI+": 0.55, "ESI-": 0.6}, "aryl methoxy group"], ["C4H8", "[O,N,S]C([CH3])([CH3])[CH3]", [1, 2, 3, 4], 0, 8, false, {"EI": 0.5, "ESI+": 0.8, "ESI-": 0.3}, "tert-butyl group"], ["C2H2O", "[O,N;!$([O,N]C(=O)C(=O))]C(=O)[CH3]", [1, 2, 3], 0, 2, false, {"EI": 0.75, "ESI+": 0.7, "ESI-": 0.4}, "acetyl group, as ketene"], ["HCl", "[CX4;!H0,$(C[C;!H0])][Cl]", [1], 0, 1, false, {"EI": 0.45, "ESI+": 0.4, "ESI-": 0.2}, "alkyl chloride"], ["HBr", "[CX4;!H0,$(C[C;!H0])][Br]", [1], 0, 1, false, {"EI": 0.3, "ESI+": 0.3}, "alkyl bromide"], ["HF", "[CX4;!H0,$(C[C;!H0])][F]", [1], 0, 1, false, {"EI": 0.35, "ESI+": 0.4}, "alkyl fluoride"], ["NO2•", "[#6][$([NX3](=O)=O),$([NX3+](=O)[O-])](~[OX1])~[OX1]", [1, 2, 3], 0, 0, true, {"EI": 0.6, "ESI-": 0.5}, "nitro group"], ["H2S", "[CX4][SX2H1]", [1], 0, 2, false, {"EI": 0.35, "ESI+": 0.6}, "thiol"], ["SO3", "[O,N,#6]S(=O)(=O)[OX2H1,OX1-]", [1, 2, 3, 4], 0, 0, false, {"ESI+": 0.6, "ESI-": 0.85}, "sulfate / sulfonic acid"], ["H3PO4", "[#6]O[PX4](=O)([OX2H1,OX1-])[OX2H1,OX1-]", [1, 2, 3, 4, 5], 0, 3, false, {"ESI+": 0.8, "ESI-": 0.4}, "phosphate ester"], ["HPO3", "[#6]O[PX4](=O)([OX2H1,OX1-])[OX2H1,OX1-]", [2, 3, 4, 5], 1, 1, false, {"ESI-": 0.6, "ESI+": 0.3}, "phosphate ester"], ["CH3•", "[Si]([CH3])([CH3])[CH3]", [1], 0, 3, true, {"EI": 0.75}, "trimethylsilyl group"], ["C4H9•", "[Si]([CH3])([CH3])C([CH3])([CH3])[CH3]", [3, 4, 5, 6], 0, 9, true, {"EI": 0.9}, "tert-butyldimethylsilyl group"]], "FORMULA_LOSSES": [["CO", "[#6;R][#6X3;R](=O)[#6;R]", {"C": 1, "O": 1}, false, {"EI": 0.45, "ESI+": 0.55, "ESI-": 0.4}, "ring C=O (from the ring)"], ["CO2", "[#6;R](=O)[O,o;R]", {"C": 1, "O": 2}, false, {"EI": 0.45, "ESI+": 0.35, "ESI-": 0.5}, "lactone / coumarin (from the ring)"], ["CO2", "O=[#6;R]1[#6;R]~[#6;R][O,o;R][#6;R]~[#6;R]1", {"C": 1, "O": 2}, false, {"ESI+": 0.2, "ESI-": 0.4}, "chromone C ring (from the ring)"], ["C2H2O", "O=[#6;R]1[#6;R]~[#6;R][O,o;R][#6;R]~[#6;R]1", {"C": 2, "H": 2, "O": 1}, false, {"ESI+": 0.35}, "chromone C ring, as ketene (from the ring)"], ["CO", "c[OX2H1]", {"C": 1, "O": 1}, false, {"EI": 0.4, "ESI+": 0.2, "ESI-": 0.3}, "phenol (from the ring)"], ["NO•", "[#6][$([NX3](=O)=O),$([NX3+](=O)[O-])]", {"N": 1, "O": 1}, true, {"EI": 0.4, "ESI-": 0.35}, "nitro group (as the nitrite)"], ["HCN", "[n,$([NX3H2]c)]", {"C": 1, "N": 1, "H": 1}, false, {"EI": 0.35, "ESI+": 0.25}, "aromatic N"], ["C3H6O3", "[c][CX4;R1]1[OX2;R1][CX4;R1][CX4;R1][CX4;R1][CX4;R1]1", {"C": 3, "H": 6, "O": 3}, false, {"ESI+": 0.55, "ESI-": 0.7}, "C-glycoside (cross-ring, 0,3X)"], ["C4H8O4", "[c][CX4;R1]1[OX2;R1][CX4;R1][CX4;R1][CX4;R1][CX4;R1]1", {"C": 4, "H": 8, "O": 4}, false, {"ESI+": 0.55, "ESI-": 0.75}, "C-glycoside (cross-ring, 0,2X)"], ["CH3OH", "c([OX2H1,NX3H2,NX3H1])c[CX3](=O)[OX2][CH3]", {"C": 1, "H": 4, "O": 1}, false, {"EI": 0.8}, "ortho effect"], ["C2H5OH", "c([OX2H1,NX3H2,NX3H1])c[CX3](=O)[OX2][CH2][CH3]", {"C": 2, "H": 6, "O": 1}, false, {"EI": 0.8}, "ortho effect"], ["H2O", "c([OX2H1,NX3H2,NX3H1,CH3])c[CX3](=O)[OX2H1]", {"H": 2, "O": 1}, false, {"EI": 0.75}, "ortho effect"], ["CH2O", "c[OX2][CH3]", {"C": 1, "H": 2, "O": 1}, false, {"EI": 0.4}, "aryl methyl ether"], ["CHO•", "c[OX2H1]", {"C": 1, "H": 1, "O": 1}, true, {"EI": 0.3}, "phenol, as formyl"], ["C5H14NO4P", "C[N+](C)(C)CCOP(=O)([O-,OX2H1])OC", {"C": 5, "H": 14, "N": 1, "O": 4, "P": 1}, false, {"ESI+": 0.5}, "phosphocholine"], ["C2H8NO4P", "[NX3H2]CCOP(=O)([OX2H1,O-])OC", {"C": 2, "H": 8, "N": 1, "O": 4, "P": 1}, false, {"ESI+": 0.85}, "phosphoethanolamine"]], "DIAGNOSTIC": [[{"C": 3, "H": 9, "Si": 1}, false, ["[O,N,S,#6][Si]([CH3])([CH3])[CH3]", 1], {"EI": 0.85}, "trimethylsilyl ion Si(CH3)3+ (m/z 73)", "Cleavage of the X–Si bond with the charge on silicon: the trimethylsilyl cation, present in the spectrum of every TMS derivative.", "tms"], [{"C": 5, "H": 15, "O": 1, "Si": 2}, false, ["O[Si]([CH3])([CH3])[CH3]", 2], {"EI": 0.6}, "pentamethyldisiloxanyl ion (m/z 147)", "Two TMS groups close in space: a silyl group migrates to the other TMS oxygen and (CH3)2Si=O+–Si(CH3)3 forms; it shows two or more TMS–O groups.", "tms"], [{"C": 5, "H": 15, "N": 1, "O": 4, "P": 1}, false, ["C[N+](C)(C)CCOP(=O)([O-,OX2H1])O", 1], {"ESI+": 0.95}, "phosphocholine ion (m/z 184)", "The protonated phosphate of a phosphatidylcholine / sphingomyelin breaks at the glycerol C–O bond; the charge stays on the phosphocholine head group. Precursor scans of m/z 184 find choline lipids.", "lipid"], [{"C": 8, "H": 14, "N": 1, "O": 5}, false, ["[CX4;R1]1([OX2])[CX4;R1](NC(=O)[CH3])[CX4;R1][CX4;R1][CX4;R1]O1", 1], {"ESI+": 0.8}, "HexNAc oxonium ion (m/z 204)", "Glycosidic cleavage with the charge on the N-acetylhexosamine (B1 oxonium ion); it then loses water (186, 168) and C2H4O2 (138, 126) - the marker of glycopeptides.", "glyco"]], "SODIUM_LOSSES": [["CO2", "[#6][CX3](=O)[OX2H1]", {"C": 1, "O": 2}, 0.6, "The sodium carboxylate-like complex loses CO2 (decarboxylation stays possible with Na+ bound)."], ["H2O", "[CX4][OX2H1]", {"H": 2, "O": 1}, 0.25, "Water loss is weak from sodium adducts: Na+ does not protonate the OH, so there is no good leaving group."], ["C2H4O2", "[CX4;R1]1[OX2;R1][CX4;R1][CX4;R1][CX4;R1][CX4;R1]1", {"C": 2, "H": 4, "O": 2}, 0.45, "Cross-ring cleavage of the sugar (0,4A / 2,4A, −60): sodium holds the ring oxygens, so the ring breaks across instead of at the glycosidic bond."], ["C3H6O3", "[CX4;R1]1[OX2;R1][CX4;R1][CX4;R1][CX4;R1][CX4;R1]1", {"C": 3, "H": 6, "O": 3}, 0.4, "Cross-ring cleavage of the sugar (0,3X, −90), typical of sodiated glycosides."], ["C4H8O4", "[CX4;R1]1[OX2;R1][CX4;R1][CX4;R1][CX4;R1][CX4;R1]1", {"C": 4, "H": 8, "O": 4}, 0.4, "Cross-ring cleavage of the sugar (0,2X, −120), typical of sodiated glycosides."], ["C3H9N", "C[N+](C)(C)CCOP(=O)([O-,OX2H1])O", {"C": 3, "H": 9, "N": 1}, 0.9, "Sodiated phosphatidylcholines lose trimethylamine (−59) first, then the cyclophosphane (−183 total)."], ["C5H14NO4P", "C[N+](C)(C)CCOP(=O)([O-,OX2H1])O", {"C": 5, "H": 14, "N": 1, "O": 4, "P": 1}, 0.5, "The phosphocholine head group leaves (−183) and the sodiated diacylglycerol ion remains."], ["C5H13NNaO4P", "C[N+](C)(C)CCOP(=O)([O-,OX2H1])O", {"C": 5, "H": 13, "N": 1, "Na": 1, "O": 4, "P": 1}, 0.6, "Sodium cholinephosphate leaves (−205): the diacylglycerol keeps the charge as a carbocation / dioxolanylium."]]};
